"C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '$rows = Import-Csv -LiteralPath "C:'"\\Users\\hzq00\\Documents\\Codex\\2026-08-22\\c-program-files-x86-honorsuite\\work\\stage2_20260823-000955\\adjudication\\A03\\STATE_DIFF.tsv\" -Delimiter \""'`t"
